{
  "platform": "host",
  "provider": "Service",
  "method": "listService",
  "data": {
    "mode": "service",
    "service": {
      "key": "fusionParticipants",
      "description": "Loader-mounted task owner; exposes no model tools or product activation operation.",
      "access": {
        "optional": {
          "expression": "ctx.get(\"fusionParticipants\")",
          "requiresUndefinedCheck": true
        },
        "hardDependency": {
          "inject": [
            "fusionParticipants"
          ],
          "expression": "ctx.fusionParticipants"
        }
      },
      "methods": [
        {
          "signature": "prepare(selectionId: string, signal?: AbortSignal): Promise<PreparedParticipants>",
          "description": "Capture one exact selection and prepare inert durable participant contexts.",
          "parameters": [
            {
              "name": "selectionId",
              "description": "named immutable fusion-config selection."
            },
            {
              "name": "signal",
              "description": "optional cancellation; owner disposal always cancels preparation."
            }
          ],
          "returns": "prepared capability only after every writer passes its own durability barrier."
        },
        {
          "signature": "recover(rootSessionId: SessionId, signal?: AbortSignal): Promise<PreparedParticipants>",
          "description": "Recover the root and persisted participants under root-first leases.",
          "parameters": [
            {
              "name": "rootSessionId",
              "description": "persisted root identity; absence/corruption is a blocking failure."
            },
            {
              "name": "signal",
              "description": "optional cancellation; omission keeps owner disposal cancellation."
            }
          ],
          "returns": "a prepared capability using the original roster and context lineages."
        },
        {
          "signature": "registerExecutionHost(task: PreparedParticipants, provider: ExecutionHostProvider): Promise<TaskExecutionHost>",
          "description": "Enroll one trusted held host on this exact prepared task. The declaring fiber owns withdrawal; its teardown fences admission immediately and joins cleanup before releasing dependencies. No provider, capability or callback is transported through model tools or SDK requests.",
          "parameters": [
            {
              "name": "task",
              "description": "exact live object returned by this service, never a roster or snapshot copy."
            },
            {
              "name": "provider",
              "description": "one exact provider identity per task incarnation and declaring fiber."
            }
          ],
          "returns": "memoized enrollment after exact retained writer reservations; replacement refuses."
        }
      ]
    },
    "referencedTypes": [
      {
        "name": "AdmissionSnapshot",
        "declaration": "export interface AdmissionSnapshot {\n    readonly decisionInputRevision: number;\n    readonly dirtyGeneration: number;\n    readonly reservations: readonly DeliveryId[];\n    readonly transportPending: readonly DeliveryId[];\n    readonly classificationPending: readonly DeliveryId[];\n}"
      },
      {
        "name": "Agent",
        "declaration": "export interface Agent {\n    readonly id: SessionId;\n}"
      },
      {
        "name": "AgentHandle",
        "declaration": "export interface AgentHandle {\n    agent: Agent;\n    dispose(): Promise<void>;\n}"
      },
      {
        "name": "Branded",
        "declaration": "export type Branded<B extends string> = string & {\n    readonly [BRAND]: B;\n};"
      },
      {
        "name": "DeliveryCompletion",
        "declaration": "export type DeliveryCompletion = z.infer<typeof completionSchema>;"
      },
      {
        "name": "DeliveryId",
        "declaration": "export type DeliveryId = z.infer<typeof deliveryIdSchema>;"
      },
      {
        "name": "DeliveryIntent",
        "declaration": "export type DeliveryIntent = z.infer<typeof intentSchema>;"
      },
      {
        "name": "DeliveryReceipt",
        "declaration": "export interface DeliveryReceipt extends DeliveryCompletion {\n    readonly messageId: DeliveryIntent['instruction']['id'];\n}"
      },
      {
        "name": "DormantDelivery",
        "declaration": "export interface DormantDelivery {\n    admitUser(input: TextDelivery, signal?: AbortSignal): Promise<DeliveryReceipt>;\n    admitPeer(sender: Agent, input: TextDelivery, signal?: AbortSignal): Promise<DeliveryReceipt>;\n    reconcile(): Promise<void>;\n    snapshot(): AdmissionSnapshot;\n}"
      },
      {
        "name": "EffectClass",
        "declaration": "export type EffectClass = 'read' | 'mutation' | 'infrastructure';"
      },
      {
        "name": "ExecutionAttemptId",
        "declaration": "export type ExecutionAttemptId = z.infer<typeof attempt>;"
      },
      {
        "name": "ExecutionBlockReason",
        "declaration": "export type ExecutionBlockReason = 'identity' | 'lifecycle' | 'not-owner' | 'not-registered' | 'unclassified' | 'writer' | 'durability' | 'cleanup-unknown' | 'outcome-unknown';"
      },
      {
        "name": "ExecutionController",
        "declaration": "export interface ExecutionController {\n    readonly [credential]: 'controller';\n}"
      },
      {
        "name": "ExecutionHostProvider",
        "declaration": "export interface ExecutionHostProvider {\n    readonly name: string;\n    readonly revision: string;\n    classify(operation: string): EffectClass | undefined;\n    registerHeld(attempt: HeldAttempt, attemptId: ExecutionAttemptId, agent: Agent, operation: string, signal: AbortSignal): HeldProducer;\n}"
      },
      {
        "name": "ExecutionIssuer",
        "declaration": "export interface ExecutionIssuer {\n    readonly [credential]: 'issuer';\n}"
      },
      {
        "name": "ExecutionRun",
        "declaration": "export interface ExecutionRun {\n    readonly [credential]: 'run';\n}"
      },
      {
        "name": "ExecutionSettlement",
        "declaration": "export type ExecutionSettlement = {\n    readonly kind: 'settled';\n    readonly outcome: 'completed' | 'failed' | 'not-dispatched';\n} | {\n    readonly kind: 'blocked';\n    readonly reason: ExecutionBlockReason;\n    readonly attemptId: ExecutionAttemptId;\n    readonly cause: unknown;\n};"
      },
      {
        "name": "ExecutionSnapshot",
        "declaration": "export interface ExecutionSnapshot {\n    readonly incarnation: string;\n    readonly generation: number;\n    readonly owner: SessionId | null;\n    readonly phase: 'closed' | 'granted' | 'revoking' | 'blocked' | 'stopped';\n    readonly attempts: readonly {\n        readonly attemptId: ExecutionAttemptId;\n        readonly phase: string;\n    }[];\n    readonly unknown: readonly ExecutionAttemptId[];\n    readonly blockers: readonly string[];\n}"
      },
      {
        "name": "HeldAttempt",
        "declaration": "export interface HeldAttempt {\n    readonly [credential]: 'attempt';\n}"
      },
      {
        "name": "HeldProducer",
        "declaration": "export interface HeldProducer {\n    prepare(): Promise<SynchronousInvocation>;\n    cancel(reason: 'handoff' | 'stop' | 'cancel'): void;\n    cleanup(): Promise<void>;\n}"
      },
      {
        "name": "PreparedParticipants",
        "declaration": "export interface PreparedParticipants {\n    readonly roster: Roster;\n    readonly delivery: DormantDelivery;\n    readonly execution: ExecutionSnapshot;\n    adopt(role: string): Promise<AgentHandle>;\n    dispose(): Promise<void>;\n}"
      },
      {
        "name": "Roster",
        "declaration": "export type Roster = z.infer<typeof rosterSchema>;"
      },
      {
        "name": "SessionId",
        "declaration": "export type SessionId = Branded<'SessionId'>;"
      },
      {
        "name": "SynchronousInvocation",
        "declaration": "export interface SynchronousInvocation {\n    invoke(): Promise<'completed' | 'failed' | 'uncertain'>;\n}"
      },
      {
        "name": "TaskExecutionHost",
        "declaration": "export interface TaskExecutionHost {\n    readonly issuer: ExecutionIssuer;\n    readonly controller: ExecutionController;\n    bindRun(issuer: ExecutionIssuer, agent: Agent, signal: AbortSignal): ExecutionRun;\n    reserve(run: ExecutionRun, operation: string): HeldAttempt;\n    register(attempt: HeldAttempt): Promise<void>;\n    release(attempt: HeldAttempt): Promise<ExecutionSettlement>;\n    grant(controller: ExecutionController, participant: SessionId): Promise<void>;\n    revoke(controller: ExecutionController, reason: 'handoff' | 'stop' | 'cancel'): Promise<void>;\n    dispose(): Promise<void>;\n}"
      },
      {
        "name": "TextDelivery",
        "declaration": "export interface TextDelivery {\n    readonly deliveryId: DeliveryId;\n    readonly targetParticipantId: SessionId;\n    readonly inboxTarget: 'next-turn' | 'next-step';\n    readonly correlationId: string | null;\n    readonly text: string;\n}"
      }
    ]
  }
}
